import{d as r,C as s,o as g,c as d,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十一章","description":"《正易心法》第二十一章——六子重卦，乾坤杂气：六子假乾坤为体、重卦合八卦为体，分而散之则无有定体；天地清明则六子何在，故知万事悉是假合，阴阳一气但有虚幻。","frontmatter":{"title":"正易心法·第二十一章","description":"《正易心法》第二十一章——六子重卦，乾坤杂气：六子假乾坤为体、重卦合八卦为体，分而散之则无有定体；天地清明则六子何在，故知万事悉是假合，阴阳一气但有虚幻。","category":"guide","aliases":["正易心法第二十一章","六子假合无有定实","假合"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-21.md","filePath":"yijing/zheng-yi-xin-fa/chapter-21.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-21.md"},k=r({...c,setup(u){const i=[{id:"z21-01",label:"一、悉是假合",showLabel:!0,sentences:[["六子重卦，乾坤",{text:"杂气",glossary:"zaqi"},"。悉是",{text:"假合",glossary:"jiahe"},"，无有定实。"]],note:["六子与重卦，是乾坤二气相互混杂的产物；全都是借助外力拼合而成，没有固定不变的实体。（**本章是第二十章的直接对照**：第二十章说乾坤是真体（本之自然、无所假合），本章说六子重卦是假合（乾坤杂气、无有定实）——**真体永恒，假合无常**，这是全书的最终二元结构。）"]},{id:"z21-02",label:"二、假体与合体",showLabel:!0,sentences:[["六子",{text:"假乾坤以为体",glossary:"jiaQiankun"},"，重卦合八卦以为体。若",{text:"分而散之",glossary:"fenErSanzhi"},"，则六子重卦皆无有定体也。"]],note:["六子借乾坤作为自己的体，重卦以两个八卦合并为体。如果把它们分解散开，则六子与重卦都没有固定的本体。（**两层「假」**：第一层，六子借乾坤之爻而成体（震＝坤体＋乾初爻）；第二层，重卦由两个三爻卦拼合而成（泰＝上坤＋下乾）。**层层拆解，最终只剩乾坤一气。**）"]},{id:"z21-03",label:"三、天地清明",showLabel:!0,sentences:[["若今天地清明，阴阳不杂，则六子何在？六子不交，则",{text:"品物",glossary:"pinwu"},"何在？"]],note:["如果现在天地回归清明、阴阳不再混杂，那么六子在哪里？六子如果不相互交合，那么万物又在哪里？（**这是一个思想实验**：用「假设本体分离」来证明「现象是假合」——万物的存在依赖于「乾坤交合（生六子）→ 六子交合（生万物）」这条链；链条一断，万物归于虚空。**就像把一幅画的所有颜料分开——画还在吗？**）"]},{id:"z21-04",label:"四、阴阳一气但有虚幻",showLabel:!0,sentences:[["以是知人间万事，悉是假合。",{text:"阴阳一气",glossary:"yinyangYiqi"},"，但有虚幻，无有定实也。"]],note:["由此可知，人间万事全都是假合。阴阳本是一气，只有虚幻，没有固定的实体。（**「阴阳一气」是本章最深的一句**：阴和阳不是两种东西，而是同一种气的两种状态——就像冰与水，不是两种物质，而是同一物质的两种状态。**如果阴阳本是一气，那么阴阳的混杂（六子重卦）就只是「一气」在不同状态下的组合；真实的只有「一气」本身，即乾坤真体。**）"]}],o=[{id:"zaqi",term:"杂气",pinyin:"zá qì",meaning:"乾气与坤气相互混杂。六子重卦是乾坤二气杂合的产物。"},{id:"jiahe",term:"假合",pinyin:"jiǎ hé",meaning:"借合，全都是借助外力拼合而成，非自然纯粹。与第二十章「真体」对照。"},{id:"jiaQiankun",term:"假乾坤以为体",pinyin:"jiǎ qián kūn",meaning:"借乾坤作为自己的体。六子没有独立的体，借乾坤之爻而成。"},{id:"fenErSanzhi",term:"分而散之",pinyin:"fēn ér sàn zhī",meaning:"将其分解散开。把重卦拆回三爻卦，再拆回爻，最终只剩一气。"},{id:"pinwu",term:"品物",pinyin:"pǐn wù",meaning:"万事万物。宇宙中一切有形之物。"},{id:"yinyangYiqi",term:"阴阳一气",pinyin:"yīn yáng yī qì",meaning:"阴阳本是一气——不是两种东西，而是同一气的两种状态。故混杂之象但有虚幻。"}];return(b,a)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),d("div",null,[a[0]||(a[0]=t(`<h1 id="正易心法·第二十一章" tabindex="-1">正易心法·第二十一章 <a class="header-anchor" href="#正易心法·第二十一章" aria-label="Permalink to &quot;正易心法·第二十一章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是第二十章的<strong>直接对照</strong>，构成全书的最终二元结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二十章（真体）：乾坤 = 本之自然 → 无所假合 → 纯一不驳 → 倒正不变</span></span>
<span class="line"><span>第二十一章（假合）：六子重卦 = 乾坤杂气 → 悉是假合 → 驳杂不纯 → 无有定实</span></span></code></pre></div><p><strong>注解展开了三个层次的论证</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 结构论证：分而散之，无有定体</span></span>
<span class="line"><span>② 思想实验：天地清明，六子不存在</span></span>
<span class="line"><span>③ 本质揭示：阴阳一气，但有虚幻</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「分而散之」为什么能证明无定体？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任何「合」的东西，都可以被「分」</span></span>
<span class="line"><span>能被分的东西，就没有独立的定体</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六子重卦可以层层拆解，最终只剩一气 = 无有定体</span></span>
<span class="line"><span>乾坤真体不可再分 = 有定体，是最终本原</span></span></code></pre></div><p><strong>「天地清明」的思想实验</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假设：天地清明，阴阳不杂（乾回归纯阳，坤回归纯阴）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>则：六子 = 乾坤交合的产物，乾坤不交 → 六子消失</span></span>
<span class="line"><span>则：品物 = 六子交合的产物，六子不交 → 万物消失</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结论：万物的存在，依赖于「乾坤交合 → 六子交合」这条链</span></span>
<span class="line"><span>      链条一断，万物归于虚空 = 万物是假合，不是真实本体</span></span></code></pre></div><p><strong>「阴阳一气」的关键洞见</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>表层：阴阳混杂 = 假合（六子重卦）</span></span>
<span class="line"><span>深层：阴阳一气 = 本质</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阴和阳不是两种东西，而是同一种气的两种状态</span></span>
<span class="line"><span>就像冰与水：不是两种物质，而是同一物质的两种状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>推论：混杂只是「一气」在不同状态下的组合</span></span>
<span class="line"><span>      真实的只有「一气」本身 = 乾坤真体</span></span></code></pre></div><p><strong>与《道德经》的平行</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道生一，一生二，二生三，三生万物</span></span>
<span class="line"><span>道（一气／乾坤真体）→ 一（？）→ 二（阴阳）→ 三（六子）→ 万物（品物）</span></span></code></pre></div><p><strong>与佛道的共鸣</strong>：</p><table tabindex="0"><thead><tr><th>家</th><th>说法</th></tr></thead><tbody><tr><td>道家（《道德经》）</td><td>「归根曰静，是谓复命」——万物变化无常，回归根本（道）才是真实</td></tr><tr><td>佛家</td><td>「诸行无常，诸法无我」——一切现象都是因缘和合，无有定实</td></tr><tr><td>麻衣（《易》）</td><td>「六子重卦，悉是假合，无有定实」</td></tr></tbody></table><p><strong>三家共同洞见：现象世界是假合，本体才是真实。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把第二十章与本章<strong>并读</strong>：真体 ↔ 假合；</li><li>再读「分而散之」——<strong>这是本章的方法：拆解证明无定体</strong>；</li><li>最后读「阴阳一气」——<strong>这一句把「假合」的根据说透了。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>乾坤杂气</strong>：六子重卦是乾坤杂合的产物。</li><li><strong>悉是假合</strong>：借合而成，非自然纯粹。</li><li><strong>假乾坤以为体</strong>：六子借乾坤之爻而成。</li><li><strong>分而散之</strong>：拆解则无有定体。</li><li><strong>天地清明</strong>：思想实验——六子何在？品物何在？</li><li><strong>阴阳一气</strong>：只有虚幻，无有定实。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,23)),e(l,{colophon:"乾坤杂气 · 悉是假合 · 分而散之 · 阴阳一气",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十一章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"悉是假合",pinyin:["jiǎ","hé"],meaning:"全都是借助外力拼合而成。与第二十章「真体」对照——真体永恒，假合无常。"},{term:"假乾坤以为体",pinyin:["jiǎ","qián"],meaning:"六子借乾坤之爻而成体（震＝坤体＋乾初爻），没有独立的体。"},{term:"分而散之",pinyin:["fēn","ér"],meaning:"层层拆解：重卦→两个三爻卦→爻→阴阳二气。能被分的东西，没有定体。"},{term:"天地清明",pinyin:["tiān","dì"],meaning:"思想实验：设想乾坤回归纯粹、阴阳不杂，则六子与万物皆无。"},{term:"阴阳一气",pinyin:["yīn","yáng"],meaning:"阴阳不是两种东西，而是同一气的两种状态（如冰与水）——真实的只有「一气」，即乾坤真体。"}]}),a[3]||(a[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章与第二十章构成全书的最终二元结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二十章：乾坤 = 真体（本之自然、无所假合、纯一不驳、倒正不变）</span></span>
<span class="line"><span>第二十一章：六子重卦 = 假合（乾坤杂气、悉是假合、无有定实）</span></span></code></pre></div><p><strong>三个层次的论证</strong>：结构论证（分而散之）、思想实验（天地清明）、本质揭示（阴阳一气）。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「分而散之」能证明无定体</strong>：任何「合」的东西都可以被「分」；能被分的东西，就没有独立的定体。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六子重卦层层拆解 → 最终只剩一气 = 无有定体</span></span>
<span class="line"><span>乾坤真体不可再分 = 有定体，是最终本原</span></span></code></pre></div><p><strong>「无有定实」与道佛的共鸣</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道家：归根曰静，是谓复命（万物变化无常，回归根本才是真实）</span></span>
<span class="line"><span>佛家：诸行无常，诸法无我（一切现象都是因缘和合，无有定实）</span></span>
<span class="line"><span>麻衣：六子重卦，悉是假合，无有定实</span></span></code></pre></div><p><strong>三家共同洞见：现象世界是假合，本体才是真实。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li><strong>并读第二十章与本章</strong>：真体 ↔ 假合，这是全书的底盘；</li><li>记住「阴阳一气」：<strong>阴和阳不是两种东西，是同一气的两种状态</strong>（如冰与水）；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「义实通明」的「实」是什么的实？</strong> 我的看法：<strong>不是假合世界的「实」，也不是与「真体」对立的「实」——而是通过变复、在假合之中看见那个「不一不实」的一气。</strong> 换言之：<strong>「实」不是「有定实」，而是「看得见」。</strong> 麻衣说「无有定实」，却仍要「义实通明」——<strong>这两个「实」不是同一个词：前者是本体论的（有没有独立实体），后者是认识论的（是否真见）。</strong> 万物假合，故无定实；你若真见其假合，便是义实通明。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六子与重卦，是乾坤二气相互混杂的产物；全都是借助外力拼合而成，没有固定不变的实体。</p><p>六子借乾坤作为自己的体，重卦以两个八卦合并为体。如果把它们分解散开，则六子与重卦都没有固定的本体。</p><p>如果现在天地回归清明、阴阳不再混杂，那么六子在哪里？六子如果不相互交合，那么万物又在哪里？</p><p>由此可知，人间万事全都是假合。阴阳本是一气，只有虚幻，没有固定的实体。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十一章与第二十章配成一副对联——<strong>上联「乾坤真体」，下联「六子假合」；横批是一个「分」字。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「分而散之」</strong>——这是本章的方法，也是最硬的一步。<strong>能拆开的东西，就没有自己的体。</strong> 拆到最后一层，只剩一气。</li><li><strong>「假乾坤以为体」</strong>——这句话有点扎心。<strong>六子那么热闹（雷风水火山泽），居然是「借」来的体。</strong> 那么我的判断力、我的身份、我的成就，有多少也是「借来的体」？</li><li><strong>「天地清明」的思想实验</strong>——它很像一个反问：<strong>把混杂拿掉，还剩什么？</strong> 把一幅画的所有颜料分开——画还在吗？</li><li><strong>「阴阳一气」</strong>——这是全章最深的一句。<strong>阴阳不是两样东西，是一样东西的两种状态，像冰与水。</strong> 那么「对立」这个词就变得可疑：<strong>对立的两方，可能从来就是同一个东西在动。</strong></li><li><strong>与道佛的共鸣</strong>——麻衣、老子、佛家，三家说法不同，指向同一个洞见：<strong>现象是假合，本体才是真。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>第二十一章说「阴阳一气，但有虚幻，无有定实」，第二十二章说「义实通明」。如果万事虚幻，那么「义实通明」的「实」是什么的「实」？</strong> 我的看法是：<strong>这两个「实」不是一回事。</strong> 前一个「实」是<strong>本体论</strong>的（有没有独立的实体），后一个「实」是<strong>认识论</strong>的（是否真的看见了）。<strong>万物假合，所以「无有定实」；但你能看见这个「假合」，就是「义实通明」</strong>——<strong>「实」在这里是动词性的：看见了、穿透了、不再被骗。</strong> 这也解释了麻衣为什么说完「无有定实」，紧接着还要讲第二十二章的变复：<strong>不是要你在假合世界里找出实体，而是要你在假合之中看清那一气。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 六子的生成（本章说其「假」）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-11">第十一章 · 偏陂反侧</a> — 「破体」（本章的进一步解构）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-20">第二十章 · 唯乾与坤</a> — 真体（与本章构成最终对照）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-22">第二十二章 · 卦义未审</a> — 变复通明（在假合中见一气的方法）</li></ul>`,24))])}}});export{y as __pageData,k as default};
